    assign hit_anyA = | (hitA&&~data_parity_error_vectA) ;
    assign hit_anyB = | (hitB&&~data_parity_error_vectB) ;
    assign hit_anyC = | (hitC&&~data_parity_error_vectC) ;
  end

else
  begin : gen_tag_cmp_standard
    for(genvar i = 0; i<CFG.L0_LINE_COUNT; i++)
          begin : gen_cmp_fetch
        assign hit_earlyA[i] = tagA[i].vld& (tagA[i].tag[CFG.L0_EARLY_TAG_WIDTH - 1:0]==addr_tagA[CFG.L0_EARLY_TAG_WIDTH - 1:0]) ;
        assign hit_earlyB[i] = tagB[i].vld& (tagB[i].tag[CFG.L0_EARLY_TAG_WIDTH - 1:0]==addr_tagB[CFG.L0_EARLY_TAG_WIDTH - 1:0]) ;
        assign hit_earlyC[i] = tagC[i].vld& (tagC[i].tag[CFG.L0_EARLY_TAG_WIDTH - 1:0]==addr_tagC[CFG.L0_EARLY_TAG_WIDTH - 1:0]) ;
        if (CFG.L0_TAG_WIDTH==CFG.L0_EARLY_TAG_WIDTH)
                  begin : gen_hit_assign
            assign hitA[i] = hit_earlyA[i];
            assign hitB[i] = hit_earlyB[i];
            assign hitC[i] = hit_earlyC[i];
          end

        else
                  begin : gen_hit
            assign hitA[i] = hit_earlyA[i]& (tagA[i].tag[CFG.L0_TAG_WIDTH - 1:CFG.L0_EARLY_TAG_WIDTH]==addr_tagA[CFG.L0_TAG_WIDTH - 1:CFG.L0_EARLY_TAG_WIDTH]) ;
            assign hitB[i] = hit_earlyB[i]& (tagB[i].tag[CFG.L0_TAG_WIDTH - 1:CFG.L0_EARLY_TAG_WIDTH]==addr_tagB[CFG.L0_TAG_WIDTH - 1:CFG.L0_EARLY_TAG_WIDTH]) ;
            assign hitC[i] = hit_earlyC[i]& (tagC[i].tag[CFG.L0_TAG_WIDTH - 1:CFG.L0_EARLY_TAG_WIDTH]==addr_tagC[CFG.L0_TAG_WIDTH - 1:CFG.L0_EARLY_TAG_WIDTH]) ;
          end
        assign hit_prefetchA[i] = tagA[i].vld& (tagA[i].tag==addr_tag_prefetchA) ;
        assign hit_prefetchB[i] = tagB[i].vld& (tagB[i].tag==addr_tag_prefetchB) ;
        assign hit_prefetchC[i] = tagC[i].vld& (tagC[i].tag==addr_tag_prefetchC) ;
      end
    assign hit_anyA = |hitA;
    assign hit_anyB = |hitB;
    assign hit_anyC = |hitC;
    assign tag_parity_error_vectA = '0;
    assign tag_parity_error_vectB = '0;
    assign tag_parity_error_vectC = '0;
    assign invalid_tag_parity_error_vectA = '0;
    assign invalid_tag_parity_error_vectB = '0;
    assign invalid_tag_parity_error_vectC = '0;
  end
assign hit_prefetch_anyA = |hit_prefetchA;
assign hit_prefetch_anyB = |hit_prefetchB;
assign hit_prefetch_anyC = |hit_prefetchC;
assign missA = ~hit_anyA&in_valid_iA&~pending_refill_qA;
assign missB = ~hit_anyB&in_valid_iB&~pending_refill_qB;
assign missC = ~hit_anyC&in_valid_iC&~pending_refill_qC;
logic clk_inv;

tc_clk_inverter i_clk_inv (
    .clk_i(clk_i),
    .clk_o(clk_inv)
  );
if (CFG.L0_DATA_PARITY_BITS>0)
  begin : gen_tag_array_reliable
    logic [CFG.L0_DATA_PARITY_BITS - 1:0] data_parity;
    for(genvar i = 0; i<CFG.L0_DATA_PARITY_BITS; i++)
          begin : gen_data_parity
        assign data_parity[i] = ~^out_rsp_data_i[CFG.LINE_WIDTH - LineParitySplit * i - 1-:LineParitySplit];
      end
    for(genvar i = 0; i<CFG.L0_LINE_COUNT; i++)
          begin : gen_array

        always_ff @( posedge clk_i or negedge rst_ni )
          begin
            if (!rst_ni)
              begin
                tag[i].vld <= 0;
                tag[i].tag <= 0;
              end
            else
              begin
                if (evict_strb[i])
                  begin
                    tag[i].vld <= 1'b0;
                    tag[i].tag <= evict_because_prefetch ? {^addr_tag_prefetch, addr_tag_prefetch} : {^addr_tag, addr_tag};
                  end
                else
                  if (validate_strb[i])
                    begin
                      tag[i].vld <= 1'b1;
                      // invert the parity bit written at evict instead of regenerating it from the stored tag,
                      // so a tag flip while the line is refilling stays detectable after validate
                      tag[i].tag[CFG.L0_TAG_WIDTH] <= ~tag[i].tag[CFG.L0_TAG_WIDTH];
                    end

                if (flush_strb[i])
                  begin
                    tag[i].vld <= 1'b0;
                    // valid line: invert parity (~^tag -> ^tag); invalid line keeps its (inverted-code) parity.
                    // do not regenerate from the stored tag, that would mask a corrupted tag.
                    tag[i].tag[CFG.L0_TAG_WIDTH] <= tag[i].vld ? ~tag[i].tag[CFG.L0_TAG_WIDTH] : tag[i].tag[CFG.L0_TAG_WIDTH];
                  end

              end
          end
        if (CFG.EARLY_LATCH)
                  begin : gen_latch
            logic clk_vld;

            tc_clk_gating i_clk_gate (
                .clk_i(clk_inv),
                .en_i(validate_strb[i]),
                .test_en_i(1'b0),
                .clk_o(clk_vld)
              );

            always_latch
              begin
                if (clk_vld)
                  begin
                    data[i] <= {data_parity, out_rsp_data_i};
                  end

              end
          end

        else
                  begin : gen_ff

            always_ff @( posedge clk_i )
              begin
                if (validate_strb[i])
                  begin
                    data[i] <= {data_parity, out_rsp_data_i};
                  end

              end
          end
      end
  end

else
  begin : gen_tag_array_standard
    for(genvar i = 0; i<CFG.L0_LINE_COUNT; i++)
          begin : gen_array

        always_ff @( posedge clk_i or negedge rst_ni )
          begin
            if (!rst_ni)
              begin
                tag[i].vld <= 0;
                tag[i].tag <= 0;
              end
            else
              begin
                if (evict_strb[i])
                  begin
                    tag[i].vld <= 1'b0;
                    tag[i].tag <= evict_because_prefetch ? addr_tag_prefetch : addr_tag;
                  end
                else
                  if (validate_strb[i])
                    begin
                      tag[i].vld <= 1'b1;
                    end

                if (flush_strb[i])
                  begin
                    tag[i].vld <= 1'b0;
                  end

              end
          end
        if (CFG.EARLY_LATCH)
                  begin : gen_latch
            logic clk_vld;

            tc_clk_gating i_clk_gate (
                .clk_i(clk_inv),
                .en_i(validate_strb[i]),
                .test_en_i(1'b0),
                .clk_o(clk_vld)
              );

            always_latch
              begin
                if (clk_vld)
                  begin
                    data[i] <= out_rsp_data_i;
                  end

              end
          end

        else
                  begin : gen_ff

            always_ff @( posedge clk_i )
              begin
                if (validate_strb[i])
                  begin
                    data[i] <= out_rsp_data_i;
                  end

              end
          end
      end
  end
if (CFG.L0_DATA_PARITY_BITS>0)
  begin : gen_data_parity_error
    logic [CFG.L0_LINE_COUNT - 1:0] [CFG.L0_DATA_PARITY_BITS - 1:0] exp_data_parityA;
    logic [CFG.L0_LINE_COUNT - 1:0] [CFG.L0_DATA_PARITY_BITS - 1:0] exp_data_parityB;
    logic [CFG.L0_LINE_COUNT - 1:0] [CFG.L0_DATA_PARITY_BITS - 1:0] exp_data_parityC;
    for(genvar i = 0; i<CFG.L0_LINE_COUNT; i++)
          begin : gen_data_parity_error_vect
        for(genvar j = 0; j<CFG.L0_DATA_PARITY_BITS; j++)
                  begin : gen_exp_data_parity
            assign exp_data_parityA[i][j] = ~^dataA[i][CFG.LINE_WIDTH - LineParitySplit * j - 1-:LineParitySplit];
            assign exp_data_parityB[i][j] = ~^dataB[i][CFG.LINE_WIDTH - LineParitySplit * j - 1-:LineParitySplit];
            assign exp_data_parityC[i][j] = ~^dataC[i][CFG.LINE_WIDTH - LineParitySplit * j - 1-:LineParitySplit];
          end
        assign data_parity_error_vectA[i] =  (exp_data_parityA[i]!=dataA[i][CFG.LINE_WIDTH+:CFG.L0_DATA_PARITY_BITS]) &&tagA[i].vld;
        assign data_parity_error_vectB[i] =  (exp_data_parityB[i]!=dataB[i][CFG.LINE_WIDTH+:CFG.L0_DATA_PARITY_BITS]) &&tagB[i].vld;
        assign data_parity_error_vectC[i] =  (exp_data_parityC[i]!=dataC[i][CFG.LINE_WIDTH+:CFG.L0_DATA_PARITY_BITS]) &&tagC[i].vld;
      end
  end

else
  begin : gen_data_parity_norel
    assign data_parity_error_vectA = '0;
    assign data_parity_error_vectB = '0;
    assign data_parity_error_vectC = '0;
  end
assign in_ready_oA = hit_anyA&~| (hit_earlyA&(tag_parity_error_vectA|data_parity_error_vectA)) ;
assign in_ready_oB = hit_anyB&~| (hit_earlyB&(tag_parity_error_vectB|data_parity_error_vectB)) ;
assign in_ready_oC = hit_anyC&~| (hit_earlyC&(tag_parity_error_vectC|data_parity_error_vectC)) ;
logic [CFG.LINE_WIDTH - 1:0] ins_dataA;
logic [CFG.LINE_WIDTH - 1:0] ins_dataB;
logic [CFG.LINE_WIDTH - 1:0] ins_dataC;

always_comb
  begin : data_muxerA
    ins_dataA = '0;
    for(int unsigned i = 0; i<CFG.L0_LINE_COUNT; i++)
    begin
      ins_dataA |= {CFG.LINE_WIDTH{hitA[i]}}&dataA[i];
    end
    in_data_oA = ins_dataA>> (in_addr_iA[CFG.LINE_ALIGN - 1:CFG.FETCH_ALIGN]*CFG.FETCH_DW) ;
  end

always_comb
  begin : data_muxerB
    ins_dataB = '0;
    for(int unsigned i = 0; i<CFG.L0_LINE_COUNT; i++)
    begin
      ins_dataB |= {CFG.LINE_WIDTH{hitB[i]}}&dataB[i];
    end
    in_data_oB = ins_dataB>> (in_addr_iB[CFG.LINE_ALIGN - 1:CFG.FETCH_ALIGN]*CFG.FETCH_DW) ;
  end

always_comb
  begin : data_muxerC
    ins_dataC = '0;
    for(int unsigned i = 0; i<CFG.L0_LINE_COUNT; i++)
    begin
      ins_dataC |= {CFG.LINE_WIDTH{hitC[i]}}&dataC[i];
    end
    in_data_oC = ins_dataC>> (in_addr_iC[CFG.LINE_ALIGN - 1:CFG.FETCH_ALIGN]*CFG.FETCH_DW) ;
  end
if (CFG.L0_TAG_WIDTH!=CFG.L0_EARLY_TAG_WIDTH)
  begin : gen_multihit_detection

    cc_onehot #(.Width(CFG.L0_LINE_COUNT)) i_onehot_hit_earlyA (
        .d_i(hit_earlyA),
        .is_onehot_o(hit_early_is_onehotA)
      );

    cc_onehot #(.Width(CFG.L0_LINE_COUNT)) i_onehot_hit_earlyB (
        .d_i(hit_earlyB),
        .is_onehot_o(hit_early_is_onehotB)
      );

    cc_onehot #(.Width(CFG.L0_LINE_COUNT)) i_onehot_hit_earlyC (
        .d_i(hit_earlyC),
        .is_onehot_o(hit_early_is_onehotC)
      );
  end

else
  begin : gen_no_multihit_detection
    assign hit_early_is_onehotA = 1'b1;
    assign hit_early_is_onehotB = 1'b1;
    assign hit_early_is_onehotC = 1'b1;
  end
logic [$clog2(CFG.L0_LINE_COUNT) - 1:0] cnt_dA;
logic [$clog2(CFG.L0_LINE_COUNT) - 1:0] cnt_dB;
logic [$clog2(CFG.L0_LINE_COUNT) - 1:0] cnt_dC;
logic [$clog2(CFG.L0_LINE_COUNT) - 1:0] cnt_qA;
logic [$clog2(CFG.L0_LINE_COUNT) - 1:0] cnt_qB;
logic [$clog2(CFG.L0_LINE_COUNT) - 1:0] cnt_qC;
if (CFG.L0_PLRU)
  begin : gen_plru
    logic [CFG.L0_LINE_COUNT - 1:0] hit_plruA;
    logic [CFG.L0_LINE_COUNT - 1:0] hit_plruB;
    logic [CFG.L0_LINE_COUNT - 1:0] hit_plruC;
    logic [CFG.L0_LINE_COUNT - 1:0] evict_plruA;
    logic [CFG.L0_LINE_COUNT - 1:0] evict_plruB;
    logic [CFG.L0_LINE_COUNT - 1:0] evict_plruC;
    assign hit_plruA = hitA| (evict_because_missA ? evict_strbA : '0) ;
    assign hit_plruB = hitB| (evict_because_missB ? evict_strbB : '0) ;
    assign hit_plruC = hitC| (evict_because_missC ? evict_strbC : '0) ;
    assign evict_strbA = evict_reqA ? evict_plruA : '0;
    assign evict_strbB = evict_reqB ? evict_plruB : '0;
    assign evict_strbC = evict_reqC ? evict_plruC : '0;
    assign next_evictA = evict_plruA;
    assign next_evictB = evict_plruB;
    assign next_evictC = evict_plruC;
    assign cnt_dA = '0;
    assign cnt_dB = '0;
    assign cnt_dC = '0;

    plru_tree #(.ENTRIES(CFG.L0_LINE_COUNT)) i_plru_treeA (
        .clk_i(clk_iA),
        .rst_ni(rst_niA),
        .used_i(hit_plruA),
        .plru_o(evict_plruA)
      );

    plru_tree #(.ENTRIES(CFG.L0_LINE_COUNT)) i_plru_treeB (
        .clk_i(clk_iB),
        .rst_ni(rst_niB),
        .used_i(hit_plruB),
        .plru_o(evict_plruB)
      );

    plru_tree #(.ENTRIES(CFG.L0_LINE_COUNT)) i_plru_treeC (
        .clk_i(clk_iC),
        .rst_ni(rst_niC),
        .used_i(hit_plruC),
        .plru_o(evict_plruC)
      );
  end

else
  begin : gen_round_robin
    assign next_evictA = '0;
    assign next_evictB = '0;
    assign next_evictC = '0;

    always_comb
      begin : evictorA
        evict_strbA = '0;
        cnt_dA = cnt_qA;
        if (evict_reqA)
          begin
            evict_strbA = 1<<cnt_qA;
            cnt_dA = cnt_qA + 1;
            if (evict_strbA==hit_earlyA)
              begin
                evict_strbA = 1<<cnt_dA;
                cnt_dA = cnt_qA + 2;
              end

          end

      end

    always_comb
      begin : evictorB
        evict_strbB = '0;
        cnt_dB = cnt_qB;
        if (evict_reqB)
          begin
            evict_strbB = 1<<cnt_qB;
            cnt_dB = cnt_qB + 1;
            if (evict_strbB==hit_earlyB)
              begin
                evict_strbB = 1<<cnt_dB;
                cnt_dB = cnt_qB + 2;
              end

          end

      end

    always_comb
      begin : evictorC
        evict_strbC = '0;
        cnt_dC = cnt_qC;
        if (evict_reqC)
          begin
            evict_strbC = 1<<cnt_qC;
            cnt_dC = cnt_qC + 1;
            if (evict_strbC==hit_earlyC)
              begin
                evict_strbC = 1<<cnt_dC;
                cnt_dC = cnt_qC + 2;
              end

          end

      end

    always_ff @( posedge clk_iA or negedge rst_niA )
      begin
        if (!rst_niA)
          begin
            cnt_qA <= '0;
          end
        else
          begin
            cnt_qA <= cnt_dVotedA;
          end
      end

    always_ff @( posedge clk_iB or negedge rst_niB )
      begin
        if (!rst_niB)
          begin
            cnt_qB <= '0;
          end
        else
          begin
            cnt_qB <= cnt_dVotedB;
          end
      end

    always_ff @( posedge clk_iC or negedge rst_niC )
      begin
        if (!rst_niC)
          begin
            cnt_qC <= '0;
          end
        else
          begin
            cnt_qC <= cnt_dVotedC;
          end
      end
  end

always_comb
  begin : flushA
    flush_strbA = '0;
    if (hit_anyA&&!hit_early_is_onehotA)
      begin
        flush_strbA = ~hitA&hit_earlyA;
      end

    flush_strbA |= tag_parity_error_vectA;
    flush_strbA |= data_parity_error_vectA;
    flush_strbA |= invalid_tag_parity_error_vectA;
    if (flush_valid_iA)
      flush_strbA = '1;

  end

always_comb
  begin : flushB
    flush_strbB = '0;
    if (hit_anyB&&!hit_early_is_onehotB)
      begin
        flush_strbB = ~hitB&hit_earlyB;
      end

    flush_strbB |= tag_parity_error_vectB;
    flush_strbB |= data_parity_error_vectB;
    flush_strbB |= invalid_tag_parity_error_vectB;
    if (flush_valid_iB)
      flush_strbB = '1;

  end

always_comb
  begin : flushC
    flush_strbC = '0;
    if (hit_anyC&&!hit_early_is_onehotC)
      begin
        flush_strbC = ~hitC&hit_earlyC;
      end

    flush_strbC |= tag_parity_error_vectC;
    flush_strbC |= data_parity_error_vectC;
    flush_strbC |= invalid_tag_parity_error_vectC;
    if (flush_valid_iC)
      flush_strbC = '1;

  end
assign refillA.addr = addr_tagA<<CFG.LINE_ALIGN;
assign refillB.addr = addr_tagB<<CFG.LINE_ALIGN;
assign refillC.addr = addr_tagC<<CFG.LINE_ALIGN;
assign refillA.is_prefetch = 1'b0;
assign refillB.is_prefetch = 1'b0;
assign refillC.is_prefetch = 1'b0;
assign refill_validA = missA;
assign refill_validB = missB;
assign refill_validC = missC;
logic [CFG.L0_LINE_COUNT - 1:0] pending_line_refill_dA;
logic [CFG.L0_LINE_COUNT - 1:0] pending_line_refill_dB;
logic [CFG.L0_LINE_COUNT - 1:0] pending_line_refill_dC;
assign pending_line_refill_dA = evict_reqA ? evict_strbA : (pending_line_refill_qA & ~validate_strbA); // drop pending once validated so invalid+pending only means a refill in flight
assign pending_line_refill_dB = evict_reqB ? evict_strbB : (pending_line_refill_qB & ~validate_strbB); // drop pending once validated so invalid+pending only means a refill in flight
assign pending_line_refill_dC = evict_reqC ? evict_strbC : (pending_line_refill_qC & ~validate_strbC); // drop pending once validated so invalid+pending only means a refill in flight

always_ff @( posedge clk_iA )
  begin
    pending_line_refill_qA <= pending_line_refill_dVotedA;
  end

always_ff @( posedge clk_iB )
  begin
    pending_line_refill_qB <= pending_line_refill_dVotedB;
  end

always_ff @( posedge clk_iC )
  begin
    pending_line_refill_qC <= pending_line_refill_dVotedC;
  end

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        pending_refill_qA <= '0;
      end
    else
      begin
        pending_refill_qA <= pending_refill_dVotedA;
      end
  end

always_ff @( posedge clk_iB or negedge rst_niB )
  begin
    if (!rst_niB)
      begin
        pending_refill_qB <= '0;
      end
    else
      begin
        pending_refill_qB <= pending_refill_dVotedB;
      end
  end

always_ff @( posedge clk_iC or negedge rst_niC )
  begin
    if (!rst_niC)
      begin
        pending_refill_qC <= '0;
      end
    else
      begin
        pending_refill_qC <= pending_refill_dVotedC;
      end
  end

always_comb
  begin
    pending_refill_dA = pending_refill_qA;
    if (pending_refill_qA)
      begin
        if (out_rsp_valid_iA&out_rsp_ready_oA)
          begin
            pending_refill_dA = 1'b0;
          end

      end
    else
      begin
        if (refill_validA&&refill_readyA)
          begin
            pending_refill_dA = 1'b1;
          end

        if (latch_prefetchA)
          begin
            pending_refill_dA = 1'b1;
          end

      end
  end

always_comb
  begin
    pending_refill_dB = pending_refill_qB;
    if (pending_refill_qB)
      begin
        if (out_rsp_valid_iB&out_rsp_ready_oB)
          begin
            pending_refill_dB = 1'b0;
          end

      end
    else
      begin
        if (refill_validB&&refill_readyB)
          begin
            pending_refill_dB = 1'b1;
          end

        if (latch_prefetchB)
          begin
            pending_refill_dB = 1'b1;
          end

      end
  end

always_comb
  begin
    pending_refill_dC = pending_refill_qC;
    if (pending_refill_qC)
      begin
        if (out_rsp_valid_iC&out_rsp_ready_oC)
          begin
            pending_refill_dC = 1'b0;
          end

      end
    else
      begin
        if (refill_validC&&refill_readyC)
          begin
            pending_refill_dC = 1'b1;
          end

        if (latch_prefetchC)
          begin
            pending_refill_dC = 1'b1;
          end

      end
  end
assign validate_strbA = out_rsp_valid_iA ? pending_line_refill_qA : '0;
assign validate_strbB = out_rsp_valid_iB ? pending_line_refill_qB : '0;
assign validate_strbC = out_rsp_valid_iC ? pending_line_refill_qC : '0;
assign out_rsp_ready_oA = 1'b1;
assign out_rsp_ready_oB = 1'b1;
assign out_rsp_ready_oC = 1'b1;
assign in_error_oA = '0;
assign in_error_oB = '0;
assign in_error_oC = '0;
assign out_req_addr_oA = out_reqA.addr;
assign out_req_addr_oB = out_reqB.addr;
assign out_req_addr_oC = out_reqC.addr;
assign out_req_id_oA = 'b1<<{L0_ID, out_reqA.is_prefetch};
assign out_req_id_oB = 'b1<<{L0_ID, out_reqB.is_prefetch};
assign out_req_id_oC = 'b1<<{L0_ID, out_reqC.is_prefetch};

always_comb
  begin
    out_reqA = prefetchA;
    out_req_valid_oA = prefetch_validA;
    prefetch_readyA = out_req_ready_iA;
    refill_readyA = 1'b0;
    if (refill_validA)
      begin
        out_req_valid_oA = refill_validA;
        out_reqA = refillA;
        refill_readyA = out_req_ready_iA;
        prefetch_readyA = 1'b0;
      end

  end

always_comb
  begin
    out_reqB = prefetchB;
    out_req_valid_oB = prefetch_validB;
