logic [FetchPkts - 1:0] maskA;
logic [FetchPkts - 1:0] maskB;
logic [FetchPkts - 1:0] maskC;
assign maskA = '1<<in_addr_iA[CFG.LINE_ALIGN - 1:2];
assign maskB = '1<<in_addr_iB[CFG.LINE_ALIGN - 1:2];
assign maskC = '1<<in_addr_iC[CFG.LINE_ALIGN - 1:2];
