  begin : gen_pre_decode

    always_comb
      begin
        is_branch_takenA[i] = 1'b0;
        is_jalA[i] = 1'b0;
        unique casez (ins_dataA[i * 32+:32])
          riscv_instr_branch::BEQ, riscv_instr_branch::BNE, riscv_instr_branch::BLT, riscv_instr_branch::BGE, riscv_instr_branch::BLTU, riscv_instr_branch::BGEU :
            begin
              is_branch_takenA[i] = ins_dataA[i*32+31];
            end
          riscv_instr_branch::JAL :
            begin
              is_jalA[i] = 1'b1;
            end
          default : ;
        endcase
      end

    always_comb
      begin
        is_branch_takenB[i] = 1'b0;
        is_jalB[i] = 1'b0;
        unique casez (ins_dataB[i * 32+:32])
          riscv_instr_branch::BEQ, riscv_instr_branch::BNE, riscv_instr_branch::BLT, riscv_instr_branch::BGE, riscv_instr_branch::BLTU, riscv_instr_branch::BGEU :
            begin
