          riscv_instr_branch::JAL :
            begin
              is_jalB[i] = 1'b1;
            end
          default : ;
        endcase
      end

    always_comb
      begin
        is_branch_takenC[i] = 1'b0;
        is_jalC[i] = 1'b0;
        unique casez (ins_dataC[i * 32+:32])
          riscv_instr_branch::BEQ, riscv_instr_branch::BNE, riscv_instr_branch::BLT, riscv_instr_branch::BGE, riscv_instr_branch::BLTU, riscv_instr_branch::BGEU :
            begin
